SCRIPT=r'''(function(){var r=document.documentElement,l=document.getElementById("langToggle"),t=document.getElementById("themeToggle");r.dataset.lang=localStorage.getItem("gapradar-lang")||"zh";r.dataset.theme=localStorage.getItem("gapradar-theme")||"dark";function s(){t.textContent=r.dataset.theme==="dark"?(r.dataset.lang==="zh"?"浅色":"Light"):(r.dataset.lang==="zh"?"深色":"Dark");}l.onclick=function(){r.dataset.lang=r.dataset.lang==="zh"?"en":"zh";localStorage.setItem("gapradar-lang",r.dataset.lang);s();};t.onclick=function(){r.dataset.theme=r.dataset.theme==="dark"?"light":"dark";localStorage.setItem("gapradar-theme",r.dataset.theme);s();};s();})();'''

def meta(s): return SECTOR_META.get(s,(s or '其他','#91a9c0','grid'))
def icon(s): return SVG[meta(s)[2]]
def short(t,n=110): t=t or ''; return t if len(t)<=n else t[:n-1]+'…'
def logo(): return '<svg viewBox="0 0 44 44" fill="none"><circle cx="22" cy="22" r="18" stroke="#3f8de8" stroke-width="4"/><circle cx="22" cy="22" r="13" stroke="#76b9ff" stroke-width="2.2"/><path d="M22 4a18 18 0 0 1 14 6" stroke="#9bd0ff" stroke-width="3.2" stroke-linecap="round"/><path d="M8 33a18 18 0 0 1-3-10" stroke="#235baf" stroke-width="3.2" stroke-linecap="round"/></svg>'
def globe():
    dots=[]
    for y in range(38,244,13):
        for x in range(60,390,13):
            nx=(x-225)/170; ny=(y-140)/118
            if nx*nx+ny*ny<=1 and (((x*7+y*11)%31<16) or (x>225 and y<145)):
                dots.append(f'<circle cx="{x}" cy="{y}" r="1.8" fill="#4d9de0" opacity=".78"/>')
    return '<svg viewBox="0 0 450 280" fill="none"><ellipse cx="225" cy="140" rx="171" ry="119" stroke="#2e6da7" stroke-opacity=".45"/>'+''.join(dots)+'</svg>'
def art(kind,headline):
    h=(headline or '').lower()
    if 'apple' in h or 'samsung' in h or 'app' in h:
        return '<svg viewBox="0 0 500 260" preserveAspectRatio="xMidYMid slice"><rect width="500" height="260" fill="#123662"/><circle cx="390" cy="70" r="76" fill="#2f75d3" opacity=".25"/><rect x="315" y="24" width="122" height="122" rx="29" fill="#1e5cb3" opacity=".42"/></svg>'
    if kind=='regulatory_shift':
        return '<svg viewBox="0 0 500 260"><rect width="500" height="260" fill="#18304d"/><path d="M0 170 100 95l76 45 84-72 92 62 148-91v221H0Z" fill="#245077"/></svg>'
    return '<svg viewBox="0 0 500 260"><rect width="500" height="260" fill="#30472c"/><path d="M0 175 87 112l64 38 83-83 65 49 89-72 112 58v158H0Z" fill="#294c35"/><path d="M110 87v90m-30-48h60m170-57v105m-34-55h68" stroke="#d5e4d1" stroke-width="3" opacity=".5"/></svg>'

def render_dashboard(events:list[MarketEvent],output:Path,world_candidates:list[GapCandidate]|None=None,scan_stats:WorldScanStats|None=None)->None:
    output.parent.mkdir(parents=True,exist_ok=True); cs=world_candidates or []; ass=load_assessments(Path('data/world-assessments.json')); amap={a.candidate_id:a for a in ass}; pairs=[(c,amap[c.id]) for c in cs if c.id in amap]; review=[x for x in pairs if x[1].final_recommendation=='REVIEW']; watch=[x for x in pairs if x[1].final_recommendation=='WATCH']; chosen=(review+watch)[:3]; counts=Counter(getattr(c,'sector','AI & Technology') for c in cs); raw=scan_stats.raw_entries if scan_stats else len(cs)
    sector_html=''.join('<div class="sector" style="--sector:'+color+'"><div class="sectorIcon" style="background:'+color+'22;color:'+color+'">'+icon(s)+'</div><strong><span class="lang-zh">'+escape(zh)+'</span><span class="lang-en">'+escape(s)+'</span></strong><small>'+str(n)+' <span class="lang-zh">条变化</span><span class="lang-en">changes</span></small><div class="bars"><i></i><i></i><i></i><i></i><i></i></div></div>' for s,n in counts.most_common(7) for zh,color,_ in [meta(s)])
    opp_html=''
    for c,a in chosen:
        s=getattr(c,'sector','AI & Technology'); zh,_,_=meta(s); sc='review' if a.final_recommendation=='REVIEW' else 'watch'; market='消费市场' if s=='Consumer & Society' else '企业市场'; phase='早期机会' if a.final_recommendation=='REVIEW' else '持续观察'
        opp_html+='<article class="opp"><div class="oppArt">'+art(c.change_type,c.headline)+'</div><span class="badge">'+icon(s)+'<span class="lang-zh">'+escape(zh)+'</span><span class="lang-en">'+escape(s)+'</span></span><span class="badge status '+sc+'">'+escape(a.final_recommendation)+'</span><h3>'+escape(short(c.headline,76))+'</h3><p>'+escape(short(c.gap_hypothesis,118))+'</p><div class="bottommeta">'+market+'　◷ '+phase+'</div><a class="arrow" href="'+escape(c.url)+'" target="_blank">→</a></article>'
    if not opp_html: opp_html='<article class="opp"><div class="oppArt">'+art('','')+'</div><h3>今天没有足够证据支持的重点机会</h3><p>雷达会继续扫描，不强行制造结论。</p></article>'
    feed=''.join('<div class="row"><div class="company"><div class="companyIcon" style="color:'+meta(getattr(c,'sector','AI & Technology'))[1]+'">'+icon(getattr(c,'sector','AI & Technology'))+'</div><span class="lang-zh">'+escape(meta(getattr(c,'sector','AI & Technology'))[0])+'</span><span class="lang-en">'+escape(getattr(c,'sector','AI & Technology'))+'</span></div><div class="what"><b>'+escape(short(c.headline,105))+'</b><span>'+escape(short(c.why_now,130))+'</span></div><div class="time">'+escape((c.published_at or '刚刚')[:10])+'</div><a class="round" href="'+escape(c.url)+'" target="_blank">›</a></div>' for c in cs[:10])
    now=datetime.now(timezone.utc); nxt=now+timedelta(hours=6)
    html=f'''<!doctype html><html lang="zh-CN" data-lang="zh" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GapRadar</title><style>{CSS}</style></head><body><div class="app"><aside class="sidebar"><div class="brand"><div class="brandmark">{logo()}</div><div class="brandname">GapRadar</div></div><div class="slogan">See Change. Find Opportunity.</div><nav class="nav"><a class="active" href="#top"><span class="navIcon">{NAV['home']}</span><span class="lang-zh">首页</span><span class="lang-en">Home</span></a><a href="#opps"><span class="navIcon">{NAV['diamond']}</span><span class="lang-zh">今日机会</span><span class="lang-en">Today</span></a><a href="#sectors"><span class="navIcon">{NAV['bars']}</span><span class="lang-zh">行业雷达</span><span class="lang-en">Sector Radar</span></a><a href="#feed"><span class="navIcon">{NAV['globe']}</span><span class="lang-zh">全球动态</span><span class="lang-en">Global Feed</span></a><a href="#"><span class="navIcon">{NAV['bookmark']}</span><span class="lang-zh">收藏夹</span><span class="lang-en">Saved</span></a></nav><div class="sidefoot">A calmer<br>smarter way<br>to see what's next.<span class="rule"></span>AMAZING KIMI</div></aside><main class="content" id="top"><div class="topline"><span class="pill">最后更新 {now.strftime('%Y-%m-%d %H:%M')} UTC</span><span class="pill live">● 下次更新 {nxt.strftime('%H:%M')} UTC</span><button class="control" id="langToggle">中 / EN</button><button class="control" id="themeToggle">浅色</button></div><section class="hero"><div class="globe">{globe()}</div><div class="hero-copy"><h1>从世界的变化<br>发现<span class="grad">下一个机会</span></h1><p>我们持续扫描全球的政策、公司动态、技术进展和市场变化，<br>帮你发现可能被忽视的市场缺口。</p><div class="actions"><a class="btn primary" href="#opps">查看今日机会　→</a><a class="btn" href="#sectors">浏览行业雷达</a></div></div><div class="overview"><h2>全球正在发生变化</h2><p>我们为你持续监测，并寻找值得关注的机会。</p><div class="stats"><div><b>{raw}</b><span>今日扫描资讯</span></div><div><b>{len(cs)}</b><span>关键变化事件</span></div><div><b>{len(pairs)}</b><span>深入分析</span></div><div><b>{len(review)}</b><span>值得关注机会</span></div></div></div></section><section class="section" id="sectors"><div class="head"><div class="headleft"><h2>行业雷达</h2><p>哪些领域今天变化最活跃？</p></div><span class="more">查看全部行业　→</span></div><div class="sectors">{sector_html}</div></section><section class="section" id="opps"><div class="head"><div class="headleft"><h2>今日推荐机会</h2><p>基于最新变化，我们认为以下机会最值得关注。</p></div><span class="more">查看全部机会　→</span></div><div class="opps">{opp_html}</div></section><section class="section" id="feed"><div class="feedtop"><div class="headleft"><h2>全球重要变化</h2><p>今天发现的其他值得了解的变化。</p></div><div class="filters"><b>全部 {len(cs)}</b><span>科技</span><span>能源</span><span>监管</span><span>消费</span></div></div><div class="feed">{feed}</div></section><div class="footer">GapRadar by AMAZING KIMI · 每 6 小时自动扫描一次 · 推荐代表研究价值，不构成投资建议。</div></main></div>''' + '<script>'+SCRIPT+'</script></body></html>'
    output.write_text(html,encoding='utf-8')
